import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double chegara = Double.parseDouble(in.next());
        int rad = 0;
        int qabul = 0;
        while (in.hasNext()) {
            String tur = in.next();
            double bal = Double.parseDouble(in.next());
            if (bal >= chegara && tur.equals("0")) {
                qabul++;
            }
            if (bal < chegara && tur.equals("1")) {
                rad++;
            }
        }
        System.out.println(rad);
        System.out.println(qabul);
    }
}

